# -*- coding: utf-8 -*-
# (speaker, italiano, coreano); speaker None => didascalia, "#" => titolo di scena (nessuno dei due conta come battuta)
M, N, L, GI, SA, C = "Matteo", "Nora", "Lorenzo", "Giulia", "Sandro", "Chiara"
D = [
("#", "Scena 1 — Lunedì 17 novembre, ore 9. Sala riunioni, primo piano.", "장면 1 — 11월 17일 월요일 오전 9시. 2층 회의실."),
(None, "Sul tavolo, una brochure patinata con una foglia verde in copertina. Accanto, il portatile di Nora e il raccoglitore grigio di Lorenzo. Fuori piove sui capannoni di Scandicci.", "탁자 위에 표지에 초록 잎이 그려진 광택지 브로슈어. 그 옆에 노라의 노트북과 로렌초의 회색 바인더. 밖에선 스칸디치의 공장 지붕 위로 비가 내린다."),
(M, "Cos'è questa foglia?", "이 잎사귀는 뭐야?"),
(N, "È la proposta di una società di consulenza di Milano. Me l'hanno mandata venerdì, dopo aver visto il nostro post sulla scuola di Renzo.", "밀라노 컨설팅 회사 제안서야. 렌초 공방 학교 게시물을 보고 금요일에 보내왔어."),
(M, "(sfoglia) «Pacchetto Bollino Verde. Report di sostenibilità chiavi in mano in quindici giorni. Pelletteria Corsini: cento per cento sostenibile, impatto zero.» Impatto zero?", "(넘기며) '그린 배지 패키지. 지속가능성 보고서 턴키 방식, 15일 완성. 펠레테리아 코르시니: 100% 지속가능, 탄소 제로.' 탄소 제로?"),
(N, "Secondo loro saremmo a impatto zero comprando crediti di carbonio. Quattromilanovecento euro, crediti compresi.", "그 사람들 말로는 탄소 크레디트를 사면 우리가 탄소 제로가 된대. 4,900유로, 크레디트 포함."),
(L, "E non è neanche cara. Rispetto a un'analisi seria, costa un quarto.", "게다가 비싸지도 않아. 제대로 된 분석에 비하면 4분의 1 가격이야."),
(M, "Lorenzo, tu la firmeresti?", "로렌초, 너라면 여기 서명하겠어?"),
(L, "Io firmo i bilanci. Quelli hanno una regola: ogni numero deve avere un foglio dietro. (batte sul raccoglitore) Qui dietro «impatto zero» non c'è nessun foglio.", "난 재무제표에 서명하는 사람이야. 거기엔 규칙이 하나 있지. 숫자마다 뒤에 서류가 있어야 한다. (바인더를 두드리며) 여기 '탄소 제로' 뒤엔 서류가 한 장도 없어."),
(M, "Allora la risposta è no.", "그럼 답은 '아니오'다."),
(N, "Aspetta. Ti dico la parte scomoda prima che te la dica Rebecca. Nel suo questionario c'è una casella: «carbon neutral sì o no». E le altre marche, accanto, hanno tutte crocettato sì.", "잠깐. 레베카가 말하기 전에 불편한 얘기부터 할게. 레베카 설문지에 칸이 하나 있어. '탄소 중립 예/아니오.' 그리고 옆에 있는 다른 브랜드들은 전부 '예'에 표시했어."),
(M, "Tutte?", "전부?"),
(N, "Quasi tutte. Su undici marche italiane della sua lista, nove dicono di essere neutrali. Io ne conosco almeno quattro. Due hanno ancora il gasolio nella caldaia.", "거의 전부. 레베카 명단에 있는 이탈리아 브랜드 열하나 중에 아홉이 중립이래. 내가 아는 데만 적어도 넷이야. 그중 둘은 아직도 보일러에 경유를 때."),
(M, "Allora noi crocettiamo no.", "그럼 우린 '아니오'에 표시하자."),
(L, "E perdiamo il cliente?", "그러다 손님을 잃으면?"),
(M, "Rebecca a ottobre mi ha detto una cosa: «Cinno, non voglio la marca più verde. Voglio la marca che non mi farà finire sul giornale.» Fra tre anni l'Europa chiederà le prove. Chi ha scritto «impatto zero» senza prove, sul giornale ci finisce.", "레베카가 10월에 그랬어. '친노, 제일 초록색인 브랜드를 원하는 게 아니에요. 날 신문에 나게 만들지 않을 브랜드를 원해요.' 3년 뒤엔 유럽이 증거를 요구할 거야. 증거 없이 '탄소 제로'라고 쓴 데는 신문에 나는 거지."),
(N, "Quindi cosa scriviamo?", "그럼 뭐라고 쓰는데?"),
(M, "Tre colonne. Quello che sappiamo. Quello che non sappiamo ancora. Quello che faremo, con una data.", "세 칸. 우리가 아는 것. 아직 모르는 것. 우리가 할 것, 날짜와 함께."),
(N, "(sorride) È la struttura che volevo proporti io. Non volevo essere la prima a dire di no a quattromilanovecento euro.", "(웃으며) 그게 내가 제안하려던 구조야. 4,900유로에 처음으로 '아니'라고 하는 사람이 되기 싫었을 뿐이지."),
(L, "Io non dico di no. Dico che la colonna «non sappiamo» fa paura ai clienti.", "난 반대하는 게 아니야. '모르는 것' 칸이 손님들을 겁먹게 한다는 거지."),
(M, "Fa paura a chi vende. A chi compra fa meno paura di una bugia scoperta.", "그건 파는 사람을 겁먹게 하는 거야. 사는 사람한텐 들통난 거짓말보다 덜 무서워."),
(N, "Allora cominciamo dalla pelle. Il cuore di tutto è lì. E lì c'è Sandro.", "그럼 가죽부터 시작하자. 모든 것의 중심이 거기야. 그리고 거기엔 산드로가 있지."),
(L, "Prima una precisazione. I numeri sono sparsi in venti fogli miei: li unisco io entro stasera. E il report riguarda la linea Corsini, non il conto terzi. Per le Maison la pelle la sceglie il cliente, e spesso è conciata al cromo. Non possiamo mettere la foglia sulle loro borse.", "먼저 하나 짚자. 숫자는 내 엑셀 시트 스무 개에 흩어져 있어. 오늘 밤까지 내가 하나로 합칠게. 그리고 보고서는 코르시니 라인 얘기지, 위탁 생산이 아니야. 메종 쪽은 가죽을 고객이 고르고, 크롬 무두질인 경우가 많아. 그 사람들 가방에 잎사귀를 붙일 순 없어."),
(M, "E lo scriviamo. In prima pagina. Quante borse sono della linea Corsini, rispetto al totale?", "그것도 쓰자. 첫 페이지에. 전체에 비해 코르시니 라인 가방이 얼마나 돼?"),
(L, "Quest'anno, tra i dodici negozi e Corsini Scandicci, quasi diciottomila pezzi su circa centoventimila. Sul fatturato pesa di più, perché il prezzo è più alto: sul trenta per cento.", "올해 매장 12곳과 코르시니 스칸디치를 합쳐 약 12만 개 중에 1만 8천 개 가까이야. 매출로는 비중이 더 커, 단가가 높으니까. 30퍼센트쯤."),
(M, "Allora la prima frase è questa: «Questo report racconta meno di un decimo di quello che facciamo. Il resto lo raccontiamo l'anno prossimo.»", "그럼 첫 문장은 이거야. '이 보고서는 우리가 하는 일의 10분의 1도 안 되는 부분을 이야기합니다. 나머지는 내년에 이야기하겠습니다.'"),
(N, "Nessun consulente milanese scriverebbe una frase così.", "밀라노 컨설턴트라면 절대 이런 문장 안 쓸 거야."),
(M, "Appunto.", "그러니까."),
(L, "Rebecca però vuole numeri, non frasi. E il suo ordine dipende da questo.", "근데 레베카는 문장이 아니라 숫자를 원해. 그리고 그 사람 주문이 이거에 달려 있고."),
(M, "Lo so. Centocinquanta borse da Livorno a metà febbraio, se a dicembre ha il report sulla scrivania.", "알아. 2월 중순에 리보르노에서 가방 150개. 12월에 보고서가 책상 위에 있으면."),
(N, "E il primo trimestre è già pieno: cento per Seul a gennaio, centoventi per il Golfo entro il dieci febbraio, poi New York.", "그리고 1분기는 벌써 꽉 찼어. 1월에 서울 100개, 2월 10일까지 걸프 120개, 그다음 뉴욕."),
(M, "Per questo il report lo chiudiamo in una settimana. Non in quindici giorni come i milanesi.", "그래서 보고서는 일주일 안에 끝내는 거야. 밀라노 사람들처럼 15일이 아니라."),
(N, "In una settimana, e onesto. Va bene. Ma la grafica la decido io.", "일주일 안에, 정직하게. 좋아. 대신 디자인은 내가 정해."),

("#", "Scena 2 — Ore 11. La stessa sala. Sandro Bini in vivavoce.", "장면 2 — 오전 11시. 같은 회의실. 산드로 비니와 스피커폰 통화."),
(None, "Il telefono al centro del tavolo. Dall'altra parte si sente il rumore sordo dei bottali che girano.", "탁자 한가운데 전화기. 저편에서 무두질 통이 돌아가는 둔탁한 소리가 들린다."),
(SA, "Matteo! Allora, che m'avete combinato? Nora mi ha mandato venti domande. Venti! Il mi' commercialista me ne fa tre l'anno.", "마테오! 그래, 무슨 일을 꾸민 거야? 노라가 질문을 스무 개나 보냈어. 스무 개! 우리 세무사도 1년에 세 개 묻는데."),
(M, "Sandro, ne bastano cinque. Ma le risposte devono essere vere, anche quando sono brutte.", "산드로, 다섯 개면 돼. 대신 답은 진짜여야 해. 보기 안 좋은 답이라도."),
(SA, "Le risposte brutte sono le uniche che conosco bene. Vai.", "보기 안 좋은 답이야말로 내가 제일 잘 아는 거지. 해 봐."),
(M, "Prima: da dove vengono le pelli grezze?", "첫째. 원피는 어디서 와?"),
(SA, "Sono tutte scarti dell'industria della carne. Nessuno ammazza una vacca per fare una borsa: la borsa è quello che resta. Le compro per circa due terzi in Italia, il resto in Francia e in Spagna.", "전부 육류 산업의 부산물이야. 가방 만들려고 소를 잡는 사람은 없어. 가방은 남는 걸로 만드는 거지. 3분의 2쯤은 이탈리아에서 사고, 나머지는 프랑스랑 스페인에서."),
(N, "E fino a dove riesce a risalire? Al macello? All'allevamento?", "그럼 어디까지 거슬러 올라갈 수 있어요? 도축장까지? 농장까지?"),
(SA, "Al macello sì, per sette lotti su dieci. Ho il documento di trasporto con il numero del macello. Gli altri tre li compro da un grossista, e lui mi dice solo il paese.", "도축장까진 돼, 열 로트 중 일곱은. 도축장 번호가 적힌 운송 서류가 있어. 나머지 셋은 도매상한테 사는데, 그 사람은 나라만 알려 줘."),
(M, "E l'allevamento?", "농장은?"),
(SA, "Quello no. Un c'è nessuno, a Santa Croce, che te lo può dire onestamente. Chi te lo dice, o ha un cliente molto ricco, o racconta favole.", "그건 안 돼. 산타크로체에 그걸 정직하게 말해 줄 수 있는 사람은 아무도 없어. 그걸 말해 주는 데는 아주 부자 손님이 있거나, 동화를 지어내는 거지."),
(N, "(scrive) «Macello: settanta per cento dei lotti. Allevamento: non lo sappiamo.»", "(받아 적으며) '도축장: 로트의 70퍼센트. 농장: 모름.'"),
(SA, "Scrivilo così. Mi piace. È la prima volta che qualcuno scrive «non lo sappiamo» accanto al mio nome, e un mi vergogno.", "그렇게 써. 마음에 들어. 내 이름 옆에 누가 '모름'이라고 쓰는 건 처음인데, 부끄럽지가 않네."),
(M, "Seconda: i tannini.", "둘째. 타닌."),
(SA, "Castagno e mimosa, lo sai. Il castagno viene dai boschi del Piemonte e della Toscana, è legno di scarto delle potature. La mimosa no: viene dal Sudafrica e dal Brasile. Fa un viaggio lungo.", "밤나무랑 미모사, 알잖아. 밤나무는 피에몬테랑 토스카나 숲에서 와. 가지치기하고 남은 나무야. 미모사는 아니야. 남아프리카랑 브라질에서 와. 먼 길을 오지."),
(L, "Quindi non è tutto locale.", "그러니까 전부 현지산은 아니라는 거네."),
(SA, "Non tutto. E chi ti dice che la concia al vegetale è tutta a chilometro zero, ti vende la mimosa due volte.", "전부는 아니지. 식물성 무두질이 전부 로컬이라고 말하는 사람은 미모사를 두 번 파는 거야."),
(M, "Terza: l'acqua.", "셋째. 물."),
(SA, "L'acqua è il nostro peccato e la nostra medicina. Ne usiamo tanta. Va tutta al depuratore consortile, come per tutte le concerie del distretto. Niente cromo, perché noi il cromo un l'abbiamo. Ma non è che l'acqua esce buona da bere, eh.", "물은 우리 죄이자 우리 약이야. 많이 써. 전부 지역 공동 정화 시설로 가, 이 지구 무두질 공장 전부가 그렇듯이. 크롬은 없어. 우린 크롬을 안 쓰니까. 그렇다고 물이 마실 만해져서 나오는 건 아니야, 알지?"),
(N, "Quanti litri per una pelle?", "가죽 한 장에 몇 리터예요?"),
(SA, "Dipende. Te lo do per metro quadro, con il dato dell'anno scorso, entro venerdì. Ma un lo scrivere tondo. Scrivi il numero mio, con la virgola. E stasera ti mando anche i certificati della concia al vegetale, che li tengo io in cassaforte.", "그때그때 달라. 작년 자료로 제곱미터당 수치를 금요일까지 줄게. 대신 반올림해서 쓰지 마. 내가 주는 숫자를 소수점까지 그대로 써. 그리고 식물성 무두질 인증서도 오늘 저녁에 보내 줄게. 내 금고에 있으니까."),
(M, "Con la virgola. Promesso. Quarta: le persone. Quanti siete?", "소수점까지. 약속할게. 넷째. 사람. 몇 명이야?"),
(SA, "Trentadue. Sei sono donne, che vent'anni fa in conceria un c'era nessuna. Due vengono dal Senegal, uno dal Pakistan, gli altri sono di qui. Il più vecchio ha sessantun anni, il più giovane ventitré.", "서른둘. 여섯은 여자야. 20년 전엔 무두질 공장에 여자가 하나도 없었는데. 둘은 세네갈, 하나는 파키스탄에서 왔고 나머지는 이 동네 사람이야. 제일 나이 많은 사람이 예순하나, 제일 젊은 사람이 스물셋."),
(M, "E l'ultima. Se un cliente americano viene a Santa Croce senza avvisare, lo fai entrare?", "마지막. 미국 손님이 예고 없이 산타크로체에 오면 들여보내 줄 거야?"),
(SA, "Senza avvisare? (ride) Io lo faccio entrare. Ma la puzza gliela faccio sentire tutta. Chi vuole la pelle vera, si deve prendere anche l'odore.", "예고 없이? (웃으며) 들여보내 주지. 대신 냄새는 제대로 맡게 할 거야. 진짜 가죽을 원하면 냄새도 같이 가져가야지."),
(N, "Posso scriverlo? «Le visite non annunciate sono benvenute.»", "그거 써도 돼요? '예고 없는 방문 환영합니다.'"),
(SA, "Scrivi: «benvenute, ma portatevi le scarpe vecchie.» E Matteo, un'altra cosa.", "이렇게 써. '환영합니다, 단 헌 신발을 신고 오세요.' 그리고 마테오, 하나 더."),
(M, "Dimmi.", "말해."),
(SA, "Il mese scorso mi hanno offerto un bollino. Dovevo pagare per scrivere «conceria green». Gli ho detto che l'unica cosa verde che ho è il trattore. Se nel vostro report ci mettete la foglia, io il mio nome lo tolgo.", "지난달에 누가 나한테 인증 스티커를 팔러 왔어. 돈 내고 '친환경 무두질 공장'이라고 쓰래. 내가 가진 초록색은 트랙터밖에 없다고 했지. 너희 보고서에 잎사귀 붙이면 내 이름은 뺄 거다."),
(M, "Niente foglia, Sandro. Te lo giuro sulla mimosa.", "잎사귀 없어, 산드로. 미모사에 걸고 맹세할게."),
(SA, "(ride) Sulla mimosa un si giura, è sudafricana. Giura sul castagno.", "(웃으며) 미모사에 맹세하면 안 되지, 남아프리카 거잖아. 밤나무에 맹세해."),

("#", "Scena 3 — Ore 15.30. L'ufficio di Matteo.", "장면 3 — 오후 3시 30분. 마테오의 사무실."),
(None, "Giulia entra con lo zaino della scuola e il casco del motorino ancora in testa. Ha in mano una cartellina rossa.", "줄리아가 학교 배낭을 메고 스쿠터 헬멧을 아직 쓴 채 들어온다. 손에 빨간 서류철을 들고 있다."),
(GI, "Zio, il babbo ha detto che vi servivano «i numeri delle persone». Li ho raccolti io con Marisa. Ci ho messo tutta la settimana scorsa, dopo scuola.", "삼촌, 아빠가 '사람에 관한 숫자'가 필요하다던데요. 마리사랑 제가 모았어요. 지난주 내내 방과 후에 했어요."),
(M, "Togliti il casco, prima. Poi i numeri.", "헬멧부터 벗어. 숫자는 그다음."),
(GI, "(se lo toglie) Allora. Duecentocinquantaquattro dipendenti al trenta settembre. Il cinquantotto per cento donne. Età media quarantasei anni. Anzianità media, diciassette anni.", "(벗으며) 자. 9월 30일 기준 직원 254명. 여성 58퍼센트. 평균 나이 46세. 평균 근속 17년."),
(N, "Diciassette anni è un numero bellissimo.", "근속 17년이면 정말 멋진 숫자네."),
(GI, "Sì, ma guarda l'altro: sotto i trent'anni sono solo il nove per cento. Se togli Simone e i ragazzi della scuola, quasi nessuno.", "네, 근데 다른 것도 봐요. 서른 살 미만은 9퍼센트밖에 안 돼요. 시모네랑 학교 애들 빼면 거의 없어요."),
(M, "E questo lo scriviamo.", "그것도 쓰자."),
(GI, "Lo so. L'ho già scritto. «Il nostro problema non è tanto l'ambiente quanto l'età.» Va bene?", "알아요. 벌써 썼어요. '우리 문제는 환경이라기보다 나이다.' 괜찮아요?"),
(N, "Va benissimo. È la frase più vera della giornata.", "아주 좋아. 오늘 나온 문장 중 제일 진짜야."),
(GI, "Infortuni: tre nel duemila e ventiquattro, uno quest'anno. Un taglio di trincetto, cinque giorni di assenza. Marisa dice che con le scarpe chiuse e i guanti nuovi alla taglieria sono scesi.", "산재: 작년에 세 건, 올해 한 건. 가죽칼에 베인 거, 결근 5일. 마리사 말로는 앞막이 신발이랑 재단실 새 장갑 덕분에 줄었대요."),
(M, "E la differenza di stipendio tra uomini e donne?", "남녀 임금 차이는?"),
(GI, "(guarda la cartellina, poi Lorenzo) Questo non lo so. Marisa dice che nessuno l'ha mai calcolata.", "(서류철을 보고 로렌초를 보며) 그건 몰라요. 마리사 말로는 아무도 계산해 본 적이 없대요."),
(L, "È vero. Non l'abbiamo mai calcolata. A parità di livello, i contratti sono uguali. Ma i livelli alti sono quasi tutti uomini. Me ne vergogno un po', a dirlo davanti a te.", "맞아. 한 번도 계산 안 했어. 같은 직급이면 계약 조건은 똑같아. 그런데 높은 직급은 거의 다 남자야. 네 앞에서 말하려니 좀 부끄럽다."),
(GI, "Davanti a me? Perché?", "제 앞에서요? 왜요?"),
(L, "Perché fra vent'anni questo report lo firmi tu.", "20년 뒤엔 네가 이 보고서에 서명할 테니까."),
(M, "Allora colonna tre: «Calcoleremo la differenza di retribuzione entro marzo.» Con la data. Lorenzo, ce la fai?", "그럼 세 번째 칸에. '3월까지 임금 격차를 계산하겠습니다.' 날짜와 함께. 로렌초, 할 수 있어?"),
(L, "Ce la faccio. Ma se il numero è brutto?", "할 수 있어. 근데 숫자가 안 좋게 나오면?"),
(M, "Se il numero è brutto, l'anno dopo scriviamo quanto è migliorato.", "안 좋게 나오면, 그다음 해에 얼마나 나아졌는지 쓰면 돼."),
(GI, "Zio, posso dire una cosa sulla bozza dei milanesi? L'ha vista tutta la mia classe.", "삼촌, 밀라노 사람들 초안에 대해 하나 말해도 돼요? 우리 반 애들이 다 봤어요."),
(N, "Tutta la classe? Come?", "반 전체가? 어떻게?"),
(GI, "Avevamo educazione civica, sul greenwashing. Ho fatto vedere la copertina con la foglia senza dire di chi era. Ventidue su ventiquattro hanno detto: «È finta.»", "시민 교육 시간에 그린워싱을 배웠어요. 누구 건지 말 안 하고 잎사귀 표지를 보여 줬어요. 스물넷 중 스물둘이 '가짜다'라고 했어요."),
(M, "E gli altri due?", "나머지 둘은?"),
(GI, "Hanno detto: «È di sicuro una marca di moda.»", "'틀림없이 패션 브랜드 거다'라고 했어요."),
(None, "Nora scoppia a ridere. Lorenzo si toglie gli occhiali e si stropiccia gli occhi.", "노라가 웃음을 터뜨린다. 로렌초가 안경을 벗고 눈을 비빈다."),
(L, "Ventidue su ventiquattro. Più duri dei revisori dei conti.", "스물넷 중 스물둘. 회계 감사관보다 더 깐깐하네."),
(GI, "Noi la foglia la vediamo su tutto. Sulle bottiglie, sui jeans, sui voli. Ormai, quando vediamo una foglia, pensiamo che qualcuno stia nascondendo qualcosa.", "우린 잎사귀를 어디서나 봐요. 병에도, 청바지에도, 비행기에도. 이젠 잎사귀가 보이면 누가 뭘 숨기고 있다고 생각해요."),
(M, "Allora cosa vuoi vedere, tu, su un report?", "그럼 넌 보고서에서 뭘 보고 싶은데?"),
(GI, "Le facce. E i numeri che fanno male. Se ci sono solo numeri belli, non ci credo.", "얼굴이요. 그리고 아픈 숫자들. 좋은 숫자만 있으면 안 믿어요."),
(N, "Le facce te le do io. Leo può fotografare Sandro, Renzo, Marisa, i ragazzi della scuola. Senza ritocchi.", "얼굴은 내가 맡을게. 레오가 산드로, 렌초, 마리사, 학교 애들을 찍으면 돼. 보정 없이."),
(GI, "E sotto ogni faccia un numero vero. Sotto Renzo: «Cinquantanove anni di lavoro, artrite alle mani, tre giorni a settimana.»", "그리고 얼굴마다 진짜 숫자 하나씩. 렌초 밑엔 '근속 59년, 손 관절염, 주 3일.'"),
(M, "Questo glielo chiedi tu, a Renzo. Se dice di no, è no.", "그건 네가 렌초한테 직접 물어봐. 안 된다고 하면 안 되는 거야."),
(GI, "Glielo chiedo stasera. Mi dirà di sì. A me dice sempre di sì, poi brontola con te.", "오늘 저녁에 물어볼게요. 된다고 할 거예요. 저한텐 늘 된다고 하고, 삼촌한테 투덜대잖아요."),
(M, "E i ragazzi della scuola di Renzo li conti?", "렌초 공방 학교 애들도 세었어?"),
(GI, "A parte. Sei allievi, tre contratti di apprendistato. Renzo ha detto che il numero giusto è «sei, più uno che ha imparato due volte».", "따로요. 견습생 여섯, 견습 계약 셋. 렌초가 정확한 숫자는 '여섯, 그리고 두 번 배운 녀석 하나'래요."),
(M, "Allora scrivilo così. Con le virgolette.", "그럼 그렇게 써. 따옴표 붙여서."),

("#", "Scena 4 — Ore 19. Sala riunioni.", "장면 4 — 오후 7시. 회의실."),
(None, "Sul tavolo, la bozza stampata: dodici pagine, nessuna foglia. In copertina una foto in bianco e nero delle mani di Renzo sul banco. Lorenzo rilegge l'ultima pagina con la matita.", "탁자 위에 출력한 초안. 열두 쪽, 잎사귀는 하나도 없다. 표지엔 작업대 위 렌초의 손을 찍은 흑백 사진. 로렌초가 연필을 들고 마지막 쪽을 다시 읽는다."),
(L, "Energia. «Nel duemila e ventiquattro abbiamo consumato circa seicentoquaranta megawattora di elettricità. I pannelli sul tetto del magazzino ne producono poco meno di un quarto.» Giusto?", "에너지. '2024년에 우리는 약 640메가와트시의 전기를 썼습니다. 창고 지붕의 태양광 패널이 그중 4분의 1 조금 못 되게 생산합니다.' 맞지?"),
(M, "Giusto. E il gas?", "맞아. 가스는?"),
(L, "«Il riscaldamento è ancora a gas metano. Abbiamo chiesto due preventivi per una pompa di calore; decideremo entro giugno.» Ho evitato di scrivere «presto». Presto non è una data.", "'난방은 아직 천연가스입니다. 히트펌프 견적을 두 곳에 요청했고, 6월까지 결정하겠습니다.' '곧'이라고 쓰는 건 피했어. '곧'은 날짜가 아니니까."),
(N, "E i crediti di carbonio?", "탄소 크레디트는?"),
(M, "Una riga sola: «Non abbiamo comprato crediti di carbonio. Preferiamo ridurre prima quello che possiamo misurare.»", "한 줄만. '탄소 크레디트는 사지 않았습니다. 먼저 측정할 수 있는 것부터 줄이겠습니다.'"),
(N, "Rebecca crocetterà «no» alla casella. E poi leggerà questa riga. Secondo me, è la riga che le farà vincere la riunione con il suo capo.", "레베카는 그 칸에 '아니오'를 표시하겠지. 그리고 이 줄을 읽을 거야. 내 생각엔, 이 줄 덕분에 레베카가 상사와의 회의에서 이길 거야."),
(L, "E il dottor Han, a Seul? Anche Gaon ce l'ha chiesto.", "서울의 한 상무는? 가온도 요청했잖아."),
(M, "A Han lo mando in italiano e in coreano. La traduzione la fa Kim, che si è offerta. Ha detto: «Così almeno lo leggo davvero.»", "한 상무한테는 이탈리아어랑 한국어로 보낼 거야. 번역은 김서연 씨가 해 준대, 자원했어. '그러면 적어도 제대로 읽게 되잖아요'래."),
(L, "(posa la matita) Allora per me è chiuso. Dodici pagine, quarantadue numeri, nove «non lo sappiamo».", "(연필을 내려놓으며) 그럼 난 끝났어. 열두 쪽, 숫자 마흔둘, '모름' 아홉 개."),
(N, "Nove «non lo sappiamo» e nove date. È il report più onesto che abbia mai impaginato.", "'모름' 아홉 개에 날짜 아홉 개. 내가 편집해 본 보고서 중 제일 정직해."),
(M, "E il titolo?", "제목은?"),
(N, "Pensavo a «Quello che sappiamo». Semplice.", "'우리가 아는 것'은 어떨까 했어. 단순하게."),
(L, "Io avrei messo «Bilancio di sostenibilità duemila e venticinque». Ma io sono un ragioniere.", "난 '2025 지속가능성 보고서'라고 했겠지. 근데 난 회계사니까."),
(M, "Mettiamo tutti e due. Quello di Lorenzo sopra, piccolo. Quello di Nora sotto, grande. Il ragioniere protegge, la frase racconta.", "둘 다 쓰자. 로렌초 걸 위에 작게, 노라 걸 아래에 크게. 회계사는 지켜 주고, 문장은 이야기하고."),
(None, "Bussano. È Chiara, con un tubo di cartone sotto il braccio e i capelli bagnati di pioggia.", "노크 소리. 키아라다. 판지 통을 옆구리에 끼고, 머리는 비에 젖었다."),
(C, "Avete finito di dire la verità? Perché io vi porto un sogno, e costa caro.", "진실 말하기는 끝났어? 난 꿈을 가져왔거든. 그것도 비싼 거."),
(M, "Il report è chiuso. Che sogno?", "보고서는 끝났어. 무슨 꿈?"),
(C, "(srotola i disegni sul tavolo) Via Tornabuoni. Un negozio, sei mesi, temporary store. Il proprietario ci aspetta giovedì della settimana prossima.", "(도면을 탁자 위에 펼치며) 토르나부오니 거리. 매장 하나, 6개월, 임시 매장. 건물주가 다음 주 목요일에 보재."),
(L, "Via Tornabuoni? Sai quanto costa un metro quadro, lì?", "토르나부오니? 거기 제곱미터당 얼마인지 알아?"),
(C, "Lo so. Per questo sei mesi e non sei anni. (indica il centro del disegno) E qui, in mezzo al negozio, un banco da lavoro vero. Con qualcuno che taglia, davanti ai clienti.", "알아. 그래서 6년이 아니라 6개월이야. (도면 한가운데를 가리키며) 그리고 여기, 매장 한가운데에 진짜 작업대. 손님들 앞에서 누군가가 가죽을 자르는 거야."),
(M, "(guarda il disegno, poi la copertina del report con le mani di Renzo) È la stessa idea, Chiara. Le facce e le mani al posto della foglia.", "(도면을 보고, 렌초의 손이 있는 보고서 표지를 보며) 같은 생각이네, 키아라. 잎사귀 대신 얼굴과 손."),
(C, "Infatti. Nora, in vetrina ci mettiamo il report. Aperto alla pagina dei «non lo sappiamo».", "그러니까. 노라, 쇼윈도에 보고서를 놓자. '모름' 페이지를 펼쳐서."),
(N, "Nessuno ha mai messo un «non lo sappiamo» in vetrina in via Tornabuoni.", "토르나부오니 쇼윈도에 '모름'을 내건 사람은 아무도 없었어."),
(C, "Allora ci sarà la fila.", "그럼 줄 서겠네."),
(L, "(sottovoce) In via Tornabuoni la fila la fanno i creditori.", "(작게) 토르나부오니에선 빚쟁이들이 줄을 서지."),
(C, "Lorenzo. Stasera no.", "로렌초. 오늘 밤은 그만."),
(M, "Allora saremo i primi. Lorenzo, giovedì vieni anche tu. Il sogno lo firma Chiara, ma il contratto lo leggi tu.", "그럼 우리가 처음이 되는 거지. 로렌초, 목요일에 너도 와. 꿈엔 키아라가 서명하지만, 계약서는 네가 읽어."),
(L, "(sospira e riprende la matita) Ogni numero deve avere un foglio dietro. Anche i sogni.", "(한숨 쉬며 다시 연필을 들고) 숫자마다 뒤에 서류가 있어야 해. 꿈도."),
]

